import { VaultMarketConfig } from "@morpho-org/blue-sdk";
import { getChainId, readContract } from "viem/actions";
import { metaMorphoAbi } from "../abis.js";
import { fetchVaultMarketPublicAllocatorConfig } from "./VaultMarketPublicAllocatorConfig.js";
// biome-ignore lint/complexity/useMaxParams: TODO refactor to ≤2 params
export async function fetchVaultMarketConfig(vault, marketId, client, parameters = {}) {
    parameters.chainId ??= await getChainId(client);
    const [[cap, enabled, removableAt], pendingCap, publicAllocatorConfig] = await Promise.all([
        readContract(client, {
            ...parameters,
            address: vault,
            abi: metaMorphoAbi,
            functionName: "config",
            args: [marketId],
        }),
        readContract(client, {
            ...parameters,
            address: vault,
            abi: metaMorphoAbi,
            functionName: "pendingCap",
            args: [marketId],
        }).then(([value, validAt]) => ({ value, validAt })),
        fetchVaultMarketPublicAllocatorConfig(vault, marketId, client, parameters),
    ]);
    return new VaultMarketConfig({
        vault,
        marketId,
        cap,
        pendingCap,
        enabled,
        removableAt,
        publicAllocatorConfig,
    });
}
